<?php
if(!isset($db)){http_response_code(404);exit;}
function networkSetup(){global $db;
$db->exec("CREATE TABLE IF NOT EXISTS onb_partner_applications(user_id INT PRIMARY KEY,experience TEXT NOT NULL,agreement_version VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME NULL) ENGINE=InnoDB");
$db->exec("CREATE TABLE IF NOT EXISTS onb_partner_requests(id INT AUTO_INCREMENT PRIMARY KEY,agent_id INT NOT NULL,kind VARCHAR(20) NOT NULL,subject VARCHAR(150) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',reply TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
$db->exec("CREATE TABLE IF NOT EXISTS onb_partner_resources(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
$db->exec("CREATE TABLE IF NOT EXISTS onb_workspace_audit(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,event VARCHAR(60) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
}
function networkAction($action,$u,$admin){global $db;if(!$u)throw new RuntimeException('Sign in required.');networkSetup();agentSetup();
$db->beginTransaction();try{
if($action==='network_apply'&&!$admin){if(agentActive($u['id'])||p('agree')!=='yes'||!p('experience')||strlen(p('experience'))>5000)throw new RuntimeException('Complete the application and acknowledge the terms.');q("INSERT INTO onb_partner_applications(user_id,experience,agreement_version) VALUES(?,?,'2026-11-v1')",[$u['id'],p('experience')]);}
elseif($action==='network_review'&&$admin){$id=(int)p('id');$status=p('status');if(!in_array($status,['approved','declined'],true))throw new RuntimeException('Invalid decision.');$a=q("SELECT * FROM onb_partner_applications WHERE user_id=? AND status='pending' FOR UPDATE",[$id])->fetch();if(!$a)throw new RuntimeException('Application already reviewed.');if($status==='approved'){if(!q("SELECT id FROM users WHERE id=? AND role='traveller'",[$id])->fetchColumn())throw new RuntimeException('Invalid account.');q('INSERT INTO onb_agents(user_id,code) VALUES(?,?) ON DUPLICATE KEY UPDATE active=1',[$id,bin2hex(random_bytes(8))]);}q('UPDATE onb_partner_applications SET status=?,reviewed_at=NOW() WHERE user_id=?',[$status,$id]);}
elseif($action==='network_request'&&!$admin&&agentActive($u['id'])){if(!in_array(p('kind'),['reward','commission','support'],true)||!p('subject')||strlen(p('subject'))>150||!p('body')||strlen(p('body'))>5000)throw new RuntimeException('Complete request.');q('INSERT INTO onb_partner_requests(agent_id,kind,subject,body) VALUES(?,?,?,?)',[$u['id'],p('kind'),p('subject'),p('body')]);}
elseif($action==='network_reply'&&$admin){if(!in_array(p('status'),['open','resolved'],true)||!p('reply')||strlen(p('reply'))>5000)throw new RuntimeException('Enter a response.');q('UPDATE onb_partner_requests SET status=?,reply=? WHERE id=?',[p('status'),p('reply'),(int)p('id')]);}
elseif($action==='network_resource'&&$admin){if(!p('title')||strlen(p('title'))>150||!p('body')||strlen(p('body'))>20000)throw new RuntimeException('Enter resource title and content.');q('INSERT INTO onb_partner_resources(title,body) VALUES(?,?)',[p('title'),p('body')]);}
else throw new RuntimeException('Access denied.');
q('INSERT INTO onb_workspace_audit(user_id,event) VALUES(?,?)',[$u['id'],$action]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}go('page=partners');}
function networkView($u,$admin){if(!$u){echo '<h1>Become a travel partner</h1><p>Create a traveller account to apply.</p><a href="?page=register">Register</a> · <a href="?page=login">Sign in</a>';return;}networkSetup();agentSetup();$active=agentActive($u['id']);?>
<div class="onb-dash"><div class="dash-hero"><span>PARTNER NETWORK</span><h1><?=$admin?'Partner recruitment & support':'Partner centre'?></h1><p>Applications, resources and partner requests.</p></div>
<?php if($admin):?><h2>Applications</h2><?php foreach(q('SELECT a.*,u.name,u.email FROM onb_partner_applications a JOIN users u ON u.id=a.user_id ORDER BY a.submitted_at DESC') as $a):?><article><h3><?=h($a['name'])?> · <?=h($a['status'])?></h3><p><?=h($a['email'])?> · <?=h($a['submitted_at'])?></p><p><?=nl2br(h($a['experience']))?></p><?php if($a['status']==='pending'):form('network_review');?><input type="hidden" name="id" value="<?=$a['user_id']?>"><label>Decision<select name="status"><option>approved</option><option>declined</option></select></label><button>Save decision</button></form><?php endif;?></article><?php endforeach;?>
<h2>Publish training or marketing resource</h2><?php form('network_resource');field('title','Resource title');area('body','Training or approved promotional copy');?><button>Publish resource</button></form>
<?php elseif(!$active):$a=q('SELECT status FROM onb_partner_applications WHERE user_id=?',[$u['id']])->fetchColumn();if($a):?><p>Application status: <?=h($a)?></p><?php else:form('network_apply');area('experience','Tell us about your sales experience and travel interests');?><p>Partner application acknowledgement: commissions apply only to verified eligible sales; do not promise unapproved prices or availability, collect customer money without authorization, or contact customers without consent. Approval and a formal agreement are required before commercial activity.</p><label><input type="checkbox" name="agree" value="yes" required> I acknowledge these application conditions (2026-11-v1).</label><button>Submit application</button></form><?php endif;endif;?>
<?php if($admin||$active):?><h2>Partner resources</h2><?php foreach(q('SELECT * FROM onb_partner_resources ORDER BY id DESC') as $r):?><details><summary><?=h($r['title'])?></summary><p><?=nl2br(h($r['body']))?></p></details><?php endforeach;?>
<?php if(!$admin):?><p><a href="?page=agents">Sales, referral link, commissions and rewards</a></p><?php form('network_request');?><label>Request type<select name="kind"><option>reward</option><option>commission</option><option>support</option></select></label><?php field('subject','Subject');area('body','Details (include reward year/milestone or lead reference if relevant)');?><button>Submit request</button></form><?php endif;?>
<h2>Partner requests</h2><?php foreach(q('SELECT r.*,u.name FROM onb_partner_requests r JOIN users u ON u.id=r.agent_id'.($admin?'':' WHERE r.agent_id=?').' ORDER BY r.id DESC',$admin?[]:[$u['id']]) as $r):?><details><summary><?=h($r['subject'].' · '.$r['status'])?></summary><p><?=h($r['name'].' · '.$r['kind'])?></p><p><?=nl2br(h($r['body']))?></p><p><?=nl2br(h($r['reply']??''))?></p><?php if($admin):form('network_reply');?><input type="hidden" name="id" value="<?=$r['id']?>"><?php area('reply','Response',$r['reply']??'');?><label>Status<select name="status"><option>open</option><option>resolved</option></select></label><button>Save response</button></form><?php endif;?></details><?php endforeach;endif;?></div><?php }
function enterpriseView($u){bookingSetup();agentSetup();agentExtrasSetup();networkSetup();$metrics=['Confirmed bookings'=>"SELECT COUNT(*) FROM onb_bookings WHERE stage IN ('confirmed','completed')",'Confirmed booking value (CAD)'=>"SELECT COALESCE(SUM(price),0) FROM onb_bookings WHERE stage IN ('confirmed','completed')",'Net collected (CAD)'=>"SELECT COALESCE(SUM(CASE WHEN kind='payment' THEN amount ELSE -amount END),0) FROM onb_booking_money",'Recorded trip expenses (CAD)'=>"SELECT COALESCE(SUM(amount),0) FROM onb_booking_expenses",'New enquiries'=>"SELECT COUNT(*) FROM enquiries WHERE status='new'",'Active agents'=>"SELECT COUNT(*) FROM onb_agents WHERE active=1",'Pending applications'=>"SELECT COUNT(*) FROM onb_partner_applications WHERE status='pending'",'Open partner requests'=>"SELECT COUNT(*) FROM onb_partner_requests WHERE status='open'"];?>
<div class="onb-dash"><div class="dash-hero"><span>MANAGEMENT CONSOLE</span><h1>Welcome, <?=h($u['name'])?></h1><p>Live operational overview · CAD</p></div><div class="metrics"><?php foreach($metrics as $label=>$sql):?><article><span><?=h($label)?></span><strong><?=number_format((float)q($sql)->fetchColumn(),strpos($label,'CAD')!==false?2:0)?></strong></article><?php endforeach;?></div><p>Booking ledger only; legacy payment and expense records are not included.</p><h2>Workspaces</h2><div class="admin-shortcuts"><?php foreach(['?page=admin'=>'Trip management','?page=bookings'=>'Bookings & finance','?page=agents'=>'Agent performance','?page=partners'=>'Partner recruitment','?page=analytics'=>'Business analytics','?page=concierge'=>'Concierge','crm.php'=>'Customer CRM','operations.php'=>'Business overview','payments.php'=>'Legacy payments'] as $url=>$label):?><a href="<?=h($url)?>"><strong><?=h($label)?></strong><span>Open workspace →</span></a><?php endforeach;?></div><h2>Recent partner administration activity</h2><?php foreach(q('SELECT a.event,a.created_at,u.name FROM onb_workspace_audit a JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 15') as $r):?><p><?=h($r['created_at'].' · '.$r['name'].' · '.$r['event'])?></p><?php endforeach;?><?php form('logout');?><button>Sign out</button></form></div><?php }
